/**
 * A webpage for fetching cute pet photos. Puppies (the best) or
 * kitties will be populated on the page after the user selects their desired
 * pet type.
 */
(function() {
  "use strict";

  window.addEventListener("load", initialize);

  /*
   * Sets up the radio buttons for the Ajax Pet Gallery for a user to select what type of
   * cute pet photos they want to see (they should of course, always pick puppies)
   */
  function initialize() {
    let radios = qsa("input[name='animal']");
    for (let i = 0; i < radios.length; i++) {
      radios[i].addEventListener("change", makeRequest);
    }
  }

  /*
   * Updates the photos displayed on the page based on the current pet selection, fetching the
   * photos from the AJAX Pets API.
   */
  function makeRequest() {
  	let animal = this.value;

    fetch(`/api/pets?animal=${animal}`)
      .then(checkStatus)
      .then(response => response.json())
      .then(displayPictures)
      .catch(console.log);
  }

  /**
   * Populates the pictures section of the page with the result images,
   * replacing any previous photos.
   * @param {string[]} imgs - array of pet image sources as strings
   */
  function displayPictures(imgs) {
    clearPictures();
    for (let i = 0; i < imgs.length; i++) {
      let imgPath = imgs[i];
      let img = document.createElement("img");
      img.src = imgPath;
      img.alt = "adorable friend";
  	  id("pictures").appendChild(img);
    }
  }

  /**
   * Clears any images in the photo gallery container.
   */
  function clearPictures() {
    let imgs = qsa("#pictures img");
    for (let i = 0; i < imgs.length; i++) {
      imgs[i].remove();
    }
  }

  /* ------------------------------ Helper Functions  ------------------------------ */

  /**
   * Helper function to return the response's result text if successful, otherwise
   * returns the rejected Promise result with an error status and corresponding text
   * @param {object} response - response to check for success/error
   * @return {object} - valid result text if response was successful, otherwise rejected
   *                    Promise result
   */
  function checkStatus(response) {
    if (response.status >= 200 && response.status < 300 || response.status == 0) {
      return response;
    } else {
      return Promise.reject(new Error(response.status + ": " + response.statusText));
    }
  }

  /**
   * Returns the element that has the ID attribute with the specified value.
   * @param {string} id - element ID
   * @return {object} DOM object associated with id.
   */
  function id(id) {
    return document.getElementById(id);
  }

  /**
   * Returns the first element that matches the given CSS selector.
   * @param {string} query - CSS query selector.
   * @returns {object[]} array of DOM objects matching the query.
   */
  function qs(query) {
    return document.querySelector(query);
  }

  /**
   * Returns the array of elements that match the given CSS selector.
   * @param {string} query - CSS query selector
   * @returns {object[]} array of DOM objects matching the query.
   */
  function qsa(query) {
    return document.querySelectorAll(query);
  }
})();

/**
 * A server for delivering adorable pet photos to clients.
 * When the client requests pictures of either puppies (the best) or kitties,
 * this server responds with a JSON array of image paths.
 */

"use strict";

const express = require("express");
const path = require("path");

const app = express();
const PORT = 8080;

// Set up static file serving
app.use(express.static(__dirname));

// Route the root URL to ajaxpets.html
app.get("/", (req, res) => {
  res.sendFile(path.join(__dirname, "ajaxpets.html"));
});

// Start listening for requests
app.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}...`);
});

/**
 * Handles GET requests to the /api/pets endpoint by sending back
 * an array of image paths for the selected animal.
 */
app.get("/api/pets", (req, res) => {
  const animal = req.query.animal;

  if (animal === "puppy") {
    res.json(generateImagePaths("puppy", 49));
  } else if (animal === "kitty") {
    res.json(generateImagePaths("kitty", 13));
  } else {
    res.status(400).json({ error: "Invalid animal type. Must be 'puppy' or 'kitty'." });
  }
});

/* ------------------------------ Helper Functions ------------------------------ */

/**
 * Generates an array of image file paths for a given base name and count.
 * Adds extra files manually when needed to include uniquely named images.
 *
 * @param {string} base - base name of the image files (e.g., "puppy" or "kitty")
 * @param {number} count - number of images to include in the response
 * @returns {string[]} array of image file paths to serve
 */
function generateImagePaths(base, count) {
  let imagePaths = [];

  // Generate standard image file names (e.g., /images/puppy01.jpg)
  for (let i = 1; i <= count; i++) {
    let num = i.toString().padStart(2, "0"); // pad numbers like 01, 02, etc.
    imagePaths.push(`/images/${base}${num}.jpg`);
  }

  // Manually include a few images without padded numbers if they exist
  // These filenames are specific to the dataset
  let extras = [
    "/images/puppy1.jpg", "/images/puppy2.jpg", "/images/puppy3.jpg",
    "/images/puppy4.jpg", "/images/puppy5.jpg", "/images/puppy6.jpg",
    "/images/puppy7.jpg", "/images/puppy9.jpg"
  ];

  if (base === "puppy") {
    imagePaths = imagePaths.concat(extras);
  }

  return imagePaths;
}

'use strict';

const express = require('express');
const app = express();

/* ============================
   Exercise 1: Splendid Circles
   Endpoint: /math/circle/:r
   ============================ */
app.get('/math/circle/:r', function(req, res) {
  let r = Number(req.params.r);

  // If radius is not a number
  if (isNaN(r)) {
    return res
      .type('text')
      .status(400)
      .send('Error: radius must be a number.');
  }

  let area = Math.PI * r * r;
  let circumference = Math.PI * 2 * r;

  res.json({
    area: area,
    circumference: circumference
  });
});

/* ============================
   Exercise 2: Hello, you!
   Endpoint: /hello/name?first=&last=
   ============================ */
app.get('/hello/name', function(req, res) {
  let first = req.query.first;
  let last = req.query.last;

  let missing = [];

  if (!first) missing.push('first');
  if (!last) missing.push('last');

  if (missing.length > 0) {
    return res
      .type('text')
      .status(400)
      .send('Missing Required GET parameters: ' + missing.join(', '));
  }

  res.type('text');
  res.send(`Hello ${first} ${last}`);
});

/* ============================
   Server Setup
   ============================ */
const PORT = process.env.PORT || 8000;
app.listen(PORT);
